  // --- Hero ---
  'hero.badge':     { zh: '浏览器扩展 · Chrome &amp; Edge · Manifest V3', en: 'Browser Extension · Chrome &amp; Edge · Manifest V3', de: 'Browser-Erweiterung · Chrome &amp; Edge · Manifest V3', fr: 'Extension de navigateur · Chrome &amp; Edge · Manifest V3', es: 'Extensión de navegador · Chrome &amp; Edge · Manifest V3', pt: 'Extensão de navegador · Chrome &amp; Edge · Manifest V3' },
  'hero.line1':     { zh: '在网页上思考，', en: 'Think on any page,', de: 'Denken Sie direkt auf der Webseite –', fr: 'Pensez sur n’importe quelle page,', es: 'Piensa en cualquier página,', pt: 'Pense em qualquer página,' },
  'hero.line2':     { zh: '用批注留下你的洞察', en: 'leave your insights as annotations.', de: 'und halten Sie Ihre Erkenntnisse als Annotationen fest.', fr: 'et laissez vos idées en annotations.', es: 'y deja tus ideas como anotaciones.', pt: 'e deixe suas ideias em anotações.' },
  'hero.desc':      { zh: 'Sagitnote（天箭批注）是一款功能全面的网页标注扩展：十种标注工具、自建文档与 PDF 批注、页面快照、分享协作——<strong>注册即可免费使用</strong>。数据本地优先，云同步让标注跟随你的每一台设备。', en: 'Sagitnote is a full-featured web annotation extension: ten annotation tools, your own documents &amp; PDF annotation, page snapshots, and sharing &amp; collaboration — <strong>free to use after sign-up</strong>. Local-first data, with cloud sync that follows you across devices.', de: 'Sagitnote ist eine funktionsreiche Erweiterung zum Annotieren von Webseiten: zehn Annotation-Tools, Annotationen für eigene Dokumente &amp; PDFs, Seiten-Snapshots sowie Teilen &amp; Zusammenarbeit — <strong>nach der Registrierung kostenlos</strong>. Ihre Daten bleiben standardmäßig lokal, und der Cloud-Sync macht sie auf allen Ihren Geräten verfügbar.', fr: 'Sagitnote est une extension d’annotation web complète : dix outils d’annotation, annotation de vos propres documents et de vos PDF, instantanés de page, partage et collaboration — <strong>gratuit après inscription</strong>. Vos données restent en local par défaut, et la synchronisation cloud vous suit sur tous vos appareils.', es: 'Sagitnote es una extensión de anotación web muy completa: diez herramientas de anotación, anotación de tus propios documentos y de PDF, instantáneas de página, y compartir y colaborar — <strong>gratis tras registrarte</strong>. Tus datos se quedan en local por defecto, y la sincronización en la nube te acompaña en todos tus dispositivos.', pt: 'Sagitnote é uma extensão de anotação web completa: dez ferramentas de anotação, anotação dos seus próprios documentos e de PDFs, capturas de página, compartilhamento e colaboração — <strong>grátis depois de criar a conta</strong>. Seus dados ficam no dispositivo por padrão, e a sincronização com a nuvem segue você em todos eles.' },
  'hero.cta':       { zh: '安装扩展', en: 'Install Extension', de: 'Erweiterung installieren', fr: 'Installer l’extension', es: 'Instalar la extensión', pt: 'Instalar a extensão' },
  'hero.cta2':      { zh: '了解功能', en: 'Learn More', de: 'Funktionen entdecken', fr: 'Découvrir les fonctionnalités', es: 'Descubrir las funciones', pt: 'Conhecer os recursos' },
