  'cta.chrome':   { zh: 'Chrome 应用商店', en: 'Chrome Web Store', de: 'Chrome Web Store', fr: 'Chrome Web Store', es: 'Chrome Web Store', pt: 'Chrome Web Store' },
  'cta.version':  { zh: '当前版本 v1.0.0 · 支持 Chrome 109+ · Edge 109+', en: 'v1.0.0 · Chrome 109+ · Edge 109+', de: 'Aktuelle Version v1.0.0 · Chrome 109+ · Edge 109+', fr: 'Version actuelle v1.0.0 · Chrome 109+ · Edge 109+', es: 'Versión actual v1.0.0 · Chrome 109+ · Edge 109+', pt: 'Versão atual v1.0.0 · Chrome 109+ · Edge 109+' },

